function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function title(v){return String(v??'').replace(/[_-]+/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function clamp(v,min=0,max=1){const n=Number(v);return Number.isFinite(n)?Math.max(min,Math.min(max,n)):min;}
function pct(v){return `${Math.round(clamp(v)*100)}%`;}
function ms(v){const n=Number(v);return Number.isFinite(n)?`${n<1000?n.toFixed(n<100?1:0):(n/1000).toFixed(2)+'s'}`:'—';}
function now(){return new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});}
function toast(text){const el=$('#toast');el.textContent=String(text||'');el.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add('hidden'),2800);nativeHaptic('light');}
function nativePost(method,payload={}){try{window.webkit?.messageHandlers?.maryNative?.postMessage({method,...payload});return true;}catch(_){return false;}}
function nativeHaptic(style='light'){if(state.native)nativePost('haptic',{style});else if(navigator.vibrate)navigator.vibrate(style==='success'?[15,30,15]:10);}
function isNative(){return state.native||location.protocol==='file:'||location.protocol==='capacitor:';}
function getServer(){let value=(localStorage.getItem(STORAGE.server)||'').trim().replace(/\/+$/,'');if(!value&&!isNative()&&/^https?:$/.test(location.protocol)) value=location.origin;return value;}
function getToken(){return (localStorage.getItem(STORAGE.token)||'').trim();}
function saveConnection(server,token){const clean=String(server||'').trim().replace(/\/+$/,'');if(clean)localStorage.setItem(STORAGE.server,clean);else localStorage.removeItem(STORAGE.server);if(String(token||'').trim())localStorage.setItem(STORAGE.token,String(token).trim());else localStorage.removeItem(STORAGE.token);}
function creatorSurfaceId(){const key='mary.creatorSurfaceId';let value='';try{value=sessionStorage.getItem(key)||'';}catch(_){}if(!value){const random=globalThis.crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;value=`${isNative()?'native':'web'}-${random}`.replace(/[^a-zA-Z0-9_.:-]+/g,'-').slice(0,160);try{sessionStorage.setItem(key,value);}catch(_){}}return value;}
function cleanSessionId(value){const raw=String(value||'').trim().toLowerCase();const clean=raw.replace(/[^a-z0-9_.:-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,160);return clean||'creator-primary';}
function loadSessions(){let custom=[];try{const raw=JSON.parse(localStorage.getItem(STORAGE.sessions)||'[]');if(Array.isArray(raw))custom=raw;}catch(_){}const map=new Map();[...PRESET_SESSIONS,...custom].forEach(x=>{const id=cleanSessionId(x?.id);if(id&&!map.has(id))map.set(id,{id,label:String(x?.label||title(id)).slice(0,48)});});state.sessions=[...map.values()];state.conversationId=cleanSessionId(localStorage.getItem(STORAGE.conversation)||state.status.mobile?.conversation_id||'creator-primary');if(!map.has(state.conversationId)){state.sessions.push({id:state.conversationId,label:title(state.conversationId)});}return state.sessions;}
function saveSessions(){const presets=new Set(PRESET_SESSIONS.map(x=>x.id));const custom=state.sessions.filter(x=>!presets.has(x.id));localStorage.setItem(STORAGE.sessions,JSON.stringify(custom.slice(-20)));localStorage.setItem(STORAGE.conversation,state.conversationId);}
function currentSession(){return state.sessions.find(x=>x.id===state.conversationId)||{id:state.conversationId,label:title(state.conversationId)};}
function renderSessionSheet(){loadSessions();const root=$('#session-list');if(!root)return;root.innerHTML=state.sessions.map(x=>`<button type="button" class="session-option ${x.id===state.conversationId?'active':''}" data-session-id="${escapeHtml(x.id)}"><span><strong>${escapeHtml(x.label)}</strong><small>${escapeHtml(x.id)}</small></span><span class="tag ${x.id===state.conversationId?'ready':''}">${x.id===state.conversationId?'ACTIVE':'OPEN'}</span></button>`).join('');$$('[data-session-id]',root).forEach(b=>b.addEventListener('click',()=>switchConversation(b.dataset.sessionId)));}
function openSessions(){renderSessionSheet();openDialog($('#session-sheet'));}
async function switchConversation(id,label=''){const clean=cleanSessionId(id);if(label&&!state.sessions.some(x=>x.id===clean))state.sessions.push({id:clean,label:String(label).slice(0,48)});state.conversationId=clean;saveSessions();renderConversationMode();renderSessionSheet();try{await bridge('setConversationId',[clean]);}catch(_){}closeDialog($('#session-sheet'));appendMessage('System',`Conversation switched to ${currentSession().label}.`,'system');}
function apiUrl(path){const base=getServer();if(!base)throw new Error('Mary server is not configured on this device.');return `${base}${path}`;}
async function request(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};const token=getToken();if(token)headers.Authorization=`Bearer ${token}`;let response;try{response=await fetch(apiUrl(path),{...options,headers});}catch(e){setConnected(false);throw new Error(`Could not reach Mary. ${e?.message||e}`);}let data={};try{data=await response.json();}catch(_){}if(response.status===401){setConnected(false);openConnection();throw new Error('Mary rejected this access token.');}if(!response.ok||data.ok===false)throw new Error(data.error||`Mary server returned ${response.status}.`);return data;}
 async function lifecycle(path,body={},{keepalive=false}={}){const result=await request(`/api/lifecycle/${path}`,{method:'POST',keepalive,body:JSON.stringify(body)});state.lifecycle=result.lifecycle||{};return state.lifecycle;}
 async function registerSurface(){if(!getServer())return;try{await lifecycle('register',{surface_id:creatorSurfaceId(),visible:!document.hidden,foreground:!document.hidden,lease_seconds:90});}catch(_){}}
 async function renewSurface(activity='heartbeat'){if(!getServer()||!navigator.onLine)return;try{await lifecycle('renew',{surface_id:creatorSurfaceId(),visible:!document.hidden,foreground:!document.hidden,activity});}catch(_){}}
 async function wakeSurface(){if(!getServer()||!navigator.onLine)return;try{await lifecycle('wake',{surface_id:creatorSurfaceId()});await renewSurface('foreground');}catch(_){}}
 function disconnectSurface(){if(!getServer())return;const body=JSON.stringify({surface_id:creatorSurfaceId()});if(!getToken()&&navigator.sendBeacon){try{if(navigator.sendBeacon(apiUrl('/api/lifecycle/disconnect'),new Blob([body],{type:'application/json'})))return;}catch(_){}}lifecycle('disconnect',{surface_id:creatorSurfaceId()}, {keepalive:true}).catch(()=>{});}
async function bridge(method,args=[]){const payload=await request('/api/bridge',{method:'POST',body:JSON.stringify({method,args})});return payload.result;}
function reportRealtime(method,args=[]){bridge(method,args).catch(()=>{});}
function setConnected(ok,label){app.dataset.connection=ok?'online':'offline';$('#status-label').textContent=label||(ok?'Connected':'Offline');}
function conversationState(value){const v=String(value||'idle').toLowerCase();const root=$('#portrait-zone');$('#avatar-state-label').textContent=v.toUpperCase();if(root){root.dataset.interactionState=v;root.classList.toggle('thinking',['thinking','responding','listening','transcribing'].includes(v));}$('#thinking').classList.toggle('hidden',!['thinking','responding','transcribing'].includes(v));}
function setBusy(v){state.busy=!!v;$('#message-input').disabled=state.busy;$('#send-button').disabled=state.busy;conversationState(v?'thinking':'idle');}
function appendMessage(who,text,kind='mary'){if(kind==='mary')$$('.message-feedback').forEach(x=>x.remove());const a=document.createElement('article');a.className=`message ${kind}`;a.innerHTML=`<header><strong>${escapeHtml(who)}</strong><time>${now()}</time></header><p></p>${kind==='mary'?'<footer class="message-feedback"><span>TRAINING SIGNAL · OPTIONAL</span><button type="button" data-response-feedback="positive" aria-label="This felt like Mary">♡</button><button type="button" data-response-feedback="negative" aria-label="This did not feel like Mary">×</button></footer>':''}`;a.querySelector('p').textContent=String(text||'');$('#messages').append(a);$('#messages').scrollTop=$('#messages').scrollHeight;}
function applyStatus(s={}){state.status=s;setConnected(true);}
function applyTrace(t={}){state.trace=t||{};}
 function applyDashboard(d={}){state.dashboard=d||{};state.ecosystem=d.ecosystem||{};state.mind=d.mind||{};const live=d.live||{},character=live.character||{},emotion=d.emotion||{},core=d.core||{},mobile=d.mobile||{};if(mobile.authority==='remote_mary_core'){const coreLabel=core.ok===false?'Core unreachable':`Core ${core.architecture||'13.2'} reachable`;const life=state.lifecycle||d.mary_lifecycle||{};const lifeLabel=`Mary ${String(life.state||'SLEEPING').toUpperCase()}`;setConnected(core.ok!==false,`${coreLabel} · ${lifeLabel}`);}$('#avatar-mood').textContent=title(emotion.primary||character.mood||'neutral');if(!state.busy)conversationState(character.status||live.status||'idle');renderConversationMode();renderCurrent();}
function renderConversationMode(){const e=state.dashboard.engagement||state.status.engagement||{},ses=e.active_session||{},effective=ses.mode||e.mode||'adaptive',thread=currentSession();$$('[data-conversation-mode]').forEach(b=>b.classList.toggle('active',b.dataset.conversationMode===effective||(effective==='adaptive'&&b.dataset.conversationMode==='adaptive')));const label=$('#conversation-thread-label'),mode=$('#conversation-thread-mode');if(label)label.textContent=thread.label||title(thread.id);if(mode)mode.textContent=ses.mode?`${title(ses.mode)} · ${ses.turns_remaining||0}`:title(e.mode||'adaptive');}
function renderCurrent(){if(state.screen==='home')renderHome();else if(state.screen==='command')renderCommand();else if(state.screen==='focus')renderFocus();else if(state.screen==='workspace')renderWorkspace(state.workspace);}
 async function refresh({quiet=false}={}){try{const [h,d,t,l]=await Promise.all([request('/api/health'),request('/api/state'),request('/api/trace'),request('/api/lifecycle/status')]);state.lifecycle=l.lifecycle||{};applyStatus(h.status||{});applyTrace(t||{});applyDashboard(d||{});return true;}catch(e){setConnected(false);if(!quiet)toast(e.message);return false;}}
async function pulsePresence(){if(document.hidden||state.busy||state.audio.speaking||state.recording.recorder?.state==='recording'||!getServer())return;try{const focus=!!state.dashboard?.focus?.active||!!state.ecosystem?.focus?.active;const r=await bridge('presencePulse',[true,focus]);if(!r?.speak&&!r?.spoke)return;const text=String(r.text||r.response||'').trim();if(!text)return;const hints=r.display_hints||{};state.lastDelivery=hints.delivery_plan||r.runtime?.delivery_plan||{};state.lastPerformancePacket=r.performance_packet||hints.performance_packet||r.runtime?.performance_packet||{};appendMessage('Mary',text,'mary');const delay=applyMobilePerformance(state.lastPerformancePacket);window.setTimeout(()=>playMarySpeech(text,{userText:'',voice:{delivery_plan:state.lastDelivery,performance_packet:state.lastPerformancePacket}}),delay);nativeHaptic('light');}catch(_){}}
 function startPassiveRefresh(){clearInterval(state.refreshTicker);clearInterval(state.presenceTicker);clearInterval(state.lifecycleTicker);state.refreshTicker=setInterval(()=>{if(!document.hidden&&!state.busy&&getServer())refresh({quiet:true});},30000);state.presenceTicker=setInterval(pulsePresence,15000);state.lifecycleTicker=setInterval(()=>renewSurface('heartbeat'),45000);window.addEventListener('online',()=>{registerSurface();wakeSurface();refresh({quiet:true});pulsePresence();});window.addEventListener('offline',()=>setConnected(false,'Core offline'));window.addEventListener('pagehide',disconnectSurface);document.addEventListener('visibilitychange',()=>{renewSurface(document.hidden?'background':'foreground');if(!document.hidden&&!state.busy&&getServer()){wakeSurface();refresh({quiet:true});setTimeout(pulsePresence,1200);}});}
async function send(text,{voiceInput=false}={}){const value=String(text||'').trim();if(!value||state.busy)return;unlockAudio();stopSpeak();appendMessage('Unbe',value,'user');nativeHaptic('light');setBusy(true);try{await wakeSurface();const p=await request('/api/chat',{method:'POST',body:JSON.stringify({text:value,conversation_id:state.conversationId,voice_input:!!voiceInput})});appendMessage('Mary',p.text||'[No response]','mary');if(p.runtime?.trace)applyTrace(p.runtime.trace);state.lastTurnMind=p.runtime?.turn_mind||{};state.lastDelivery=p.runtime?.delivery_plan||p.voice?.delivery_plan||{};state.lastPerformancePacket=p.runtime?.performance_packet||p.voice?.performance_packet||p.performance_packet||{};if(p.dashboard)applyDashboard(p.dashboard);setBusy(false);const delay=applyMobilePerformance(state.lastPerformancePacket);const voice={...(p.voice||{}),delivery_plan:state.lastDelivery,performance_packet:state.lastPerformancePacket};window.setTimeout(()=>playMarySpeech(p.text||'',{userText:value,voice}),delay);nativeHaptic('success');}catch(e){setBusy(false);appendMessage('System',e.message||String(e),'system');toast(e.message||String(e));}}
let mobilePerformanceSettleTimer=null;
function cleanExpression(value){return String(value||'neutral').toLowerCase().replace(/[^a-z0-9_-]/g,'')||'neutral';}
function mobileAmbientExpression(){const live=state.dashboard?.live||{},character=live.character||{},emotion=state.dashboard?.emotion||{};return cleanExpression(emotion.primary||character.mood||'neutral');}
function settleMobilePerformance(delay=320){if(mobilePerformanceSettleTimer)window.clearTimeout(mobilePerformanceSettleTimer);mobilePerformanceSettleTimer=window.setTimeout(()=>{const root=$('#portrait-zone');if(root){root.dataset.expression=mobileAmbientExpression();root.dataset.performance='ambient';}state.lastPerformancePacket={};mobilePerformanceSettleTimer=null;},Math.max(0,Number(delay)||0));}
function applyMobilePerformance(packet={}){const root=$('#portrait-zone');if(!root)return 0;if(mobilePerformanceSettleTimer){window.clearTimeout(mobilePerformanceSettleTimer);mobilePerformanceSettleTimer=null;}const delivery=packet?.delivery||{};const reaction=packet?.pre_reaction||{};const deliveryExpression=cleanExpression(delivery.avatar_expression||mobileAmbientExpression());const expression=cleanExpression(reaction.expression||deliveryExpression);root.dataset.performance='directed';root.dataset.expression=expression;root.dataset.gaze=cleanExpression(reaction.gaze_style||delivery.gaze_style||'engaged');root.dataset.gesture=cleanExpression(delivery.gesture_style||'natural');const duration=Math.max(0,Math.min(420,Number(reaction.duration_ms)||0));if(duration>0)window.setTimeout(()=>{if(root.dataset.performance==='directed')root.dataset.expression=deliveryExpression;},duration);return String(reaction.style||'none').toLowerCase()==='none'?0:duration;}
function deviceSpeak(text,deliveryPlan={}){if(!text)return false;const baseRate=Number(localStorage.getItem(STORAGE.rate)||'1');const pace=Number(deliveryPlan?.pace||1);const rate=clamp((Number.isFinite(baseRate)?baseRate:1)*(Number.isFinite(pace)?pace:1),.75,1.35);const volume=Number(localStorage.getItem(STORAGE.volume)||'1');if(state.native){nativePost('speak',{text:String(text),rate:Number.isFinite(rate)?rate:1});return true;}if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return false;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text));u.rate=Number.isFinite(rate)?rate:1;u.volume=Number.isFinite(volume)?clamp(volume):1;u.onstart=()=>{state.audio.speaking=true;conversationState('speaking');reportRealtime('reportSpeechStarted',[]);};u.onend=()=>{state.audio.speaking=false;conversationState('idle');reportRealtime('reportSpeechEnded',['device_finished']);settleMobilePerformance(360);};u.onerror=()=>{state.audio.speaking=false;conversationState('idle');reportRealtime('reportSpeechEnded',['device_error']);settleMobilePerformance(120);};speechSynthesis.speak(u);return true;}catch(_){return false;}}
function speak(text){return deviceSpeak(text);}
function stopSpeak(){const wasSpeaking=!!state.audio.speaking;state.audio.generation+=1;if(state.audio.source){try{state.audio.source.stop();}catch(_){}state.audio.source=null;}if(state.audio.element){try{state.audio.element.pause();state.audio.element.removeAttribute('src');state.audio.element.load();}catch(_){}}if(state.audio.objectUrl){try{URL.revokeObjectURL(state.audio.objectUrl);}catch(_){}state.audio.objectUrl='';}if(state.native)nativePost('stopSpeaking');else try{speechSynthesis.cancel();}catch(_){}state.audio.speaking=false;if(wasSpeaking)reportRealtime('reportSpeechInterrupted',['client_barge_in']);conversationState('idle');settleMobilePerformance(120);}
function voiceMode(){return localStorage.getItem(STORAGE.voiceMode)||'auto';}
function voiceEnabled(){return localStorage.getItem(STORAGE.speak)!=='false'&&voiceMode()!=='off';}
function ensureMediaElement(){if(state.native)return null;if(!state.audio.element){const audio=new Audio();audio.preload='auto';audio.setAttribute('playsinline','');audio.volume=clamp(Number(localStorage.getItem(STORAGE.volume)||'1'));state.audio.element=audio;}return state.audio.element;}
function unlockAudio(){if(state.native)return;try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(AudioCtx){if(!state.audio.context)state.audio.context=new AudioCtx();if(state.audio.context.state==='suspended')state.audio.context.resume();const ctx=state.audio.context,buffer=ctx.createBuffer(1,1,22050),source=ctx.createBufferSource();source.buffer=buffer;source.connect(ctx.destination);source.start(0);}}catch(_){}try{const audio=ensureMediaElement();if(audio&&!state.audio.unlocked&&!state.audio.priming){state.audio.priming=true;audio.muted=true;audio.src='data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=';const attempt=audio.play();Promise.resolve(attempt).then(()=>{try{audio.pause();audio.currentTime=0;audio.removeAttribute('src');audio.load();}catch(_){}audio.muted=false;state.audio.unlocked=true;state.audio.priming=false;}).catch(()=>{audio.muted=false;state.audio.priming=false;});}}catch(_){} }
async function fetchServerSpeech(text,{userText='',voice={}}={}){const token=getToken();const headers={'Content-Type':'application/json'};if(token)headers.Authorization=`Bearer ${token}`;const response=await fetch(apiUrl('/api/tts'),{method:'POST',headers,body:JSON.stringify({text:String(text),user_text:String(userText||''),delivery_plan:voice.delivery_plan||{}})});if(response.status===401){setConnected(false);openConnection();throw new Error('Mary rejected this access token.');}if(!response.ok){let detail={};try{detail=await response.json();}catch(_){}const error=new Error(detail.error||detail.reason||`Server voice unavailable (${response.status}).`);error.fallback=detail.fallback||'device';throw error;}return {buffer:await response.arrayBuffer(),mime:response.headers.get('Content-Type')||'audio/mpeg',provider:response.headers.get('X-Mary-Voice-Provider')||voice.provider||'server',model:response.headers.get('X-Mary-Voice-Model')||'',cached:response.headers.get('X-Mary-Voice-Cache')==='hit'};}
async function playServerAudio(buffer,metadata={}){if(!buffer?.byteLength)return false;unlockAudio();const generation=++state.audio.generation,mime=metadata.mime||'audio/mpeg';const audio=ensureMediaElement();if(audio){try{if(state.audio.objectUrl){URL.revokeObjectURL(state.audio.objectUrl);state.audio.objectUrl='';}const blob=new Blob([buffer],{type:mime}),url=URL.createObjectURL(blob);state.audio.objectUrl=url;audio.muted=false;audio.volume=clamp(Number(localStorage.getItem(STORAGE.volume)||'1'));audio.src=url;audio.preload='auto';audio.onplay=()=>{if(generation===state.audio.generation){state.audio.speaking=true;conversationState('speaking');reportRealtime('reportSpeechStarted',[]);}};audio.onended=()=>{if(generation===state.audio.generation){state.audio.speaking=false;conversationState('idle');reportRealtime('reportSpeechEnded',['server_finished']);settleMobilePerformance(360);try{URL.revokeObjectURL(url);}catch(_){}if(state.audio.objectUrl===url)state.audio.objectUrl='';}};audio.onerror=()=>{if(generation===state.audio.generation){state.audio.speaking=false;conversationState('idle');reportRealtime('reportSpeechEnded',['server_error']);settleMobilePerformance(120);}};await audio.play();if(generation===state.audio.generation){state.audio.unlocked=true;return true;}}catch(_){try{audio.pause();}catch(_){}}}const ctx=state.audio.context;if(!ctx)return false;try{if(ctx.state==='suspended')await ctx.resume();const decoded=await ctx.decodeAudioData(buffer.slice(0));if(generation!==state.audio.generation)return false;const source=ctx.createBufferSource(),gain=ctx.createGain();gain.gain.value=clamp(Number(localStorage.getItem(STORAGE.volume)||'1'));source.buffer=decoded;source.connect(gain);gain.connect(ctx.destination);state.audio.source=source;state.audio.gain=gain;source.onended=()=>{if(generation===state.audio.generation){state.audio.source=null;state.audio.speaking=false;conversationState('idle');reportRealtime('reportSpeechEnded',['webaudio_finished']);settleMobilePerformance(360);}};state.audio.speaking=true;conversationState('speaking');reportRealtime('reportSpeechStarted',[]);source.start(0);state.audio.unlocked=true;return true;}catch(_){return false;}}
async function playMarySpeech(text,options={}){if(!voiceEnabled()||!String(text||'').trim())return;const mode=voiceMode(),delivery=options?.voice?.delivery_plan||{};if(mode==='device'){deviceSpeak(text,delivery);return;}if(mode==='server'||mode==='auto'){try{const result=await fetchServerSpeech(text,options);if(await playServerAudio(result.buffer,result)){state.status.voice={...(state.status.voice||{}),provider:result.provider,model:result.model,last_playback:result.cached?'cache':'server'};return;}if(mode==='server'){toast('Mary received server audio, but this browser blocked playback. Tap Test Mary voice once to unlock audio.');return;}}catch(e){if(mode==='server'){toast(e.message||'Mary server voice is unavailable.');return;}}}deviceSpeak(text,delivery);}
function switchScreen(name){if(name==='more'){openWorkspaces();return;}state.screen=name;state.workspace='';app.dataset.screen=name;$$('.screen').forEach(v=>v.classList.toggle('active',v.dataset.panel===name));$$('[data-conversation-mode]').forEach(b=>b.addEventListener('click',async()=>{const mode=b.dataset.conversationMode;try{if(mode==='adaptive')await bridge('setConversationMode',['adaptive']);else await bridge('beginConversationSession',[mode,mode==='deep'?10:8]);await refresh({quiet:true});toast(mode==='adaptive'?'Adaptive conversation mode.':`${title(mode)} conversation started.`);}catch(e){toast(e.message);}}));$$('.bottom-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));$('#composer-deck').classList.toggle('hidden',name!=='chat');renderCurrent();if(name!=='chat')refresh({quiet:true});nativeHaptic('light');}
function openWorkspace(name){state.screen='workspace';state.workspace=name;app.dataset.screen=name;$$('.screen').forEach(v=>v.classList.toggle('active',v.dataset.panel==='workspace'));$$('.bottom-nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='more'));$('#composer-deck').classList.add('hidden');closeDialog($('#workspace-sheet'));renderWorkspace(name);refresh({quiet:true});nativeHaptic('light');}
function openWorkspaces(){showDialog($('#workspace-sheet'));}
function showDialog(d){if(!d)return;try{d.showModal();}catch(_){d.setAttribute('open','');}}
function closeDialog(d){if(!d)return;try{d.close();}catch(_){d.removeAttribute('open');}}
function sectionHead(eyebrow,titleText,detail){return `<header class="page-head"><span>${escapeHtml(eyebrow)}</span><h1>${escapeHtml(titleText)}</h1><p>${escapeHtml(detail)}</p></header>`;}
function panel(titleText,body,badge=''){return `<article class="panel"><header><span>${escapeHtml(titleText)}</span>${badge?`<b>${escapeHtml(badge)}</b>`:''}</header>${body}</article>`;}
function list(items,renderer,empty='Nothing here yet.'){return items?.length?`<div class="list">${items.map(renderer).join('')}</div>`:`<div class="empty">${escapeHtml(empty)}</div>`;}
function dataRow(k,v){return `<div class="data-row"><span>${escapeHtml(k)}</span><strong>${escapeHtml(v??'—')}</strong></div>`;}
function renderHome(){const d=state.dashboard,e=d.emotion||{},r=d.relationship||{},eco=state.ecosystem||{},pulse=eco.companion||{},live=d.live||{},c=live.character||{},mem=d.memory_highlights||[],score=clamp(Number(r.score||0)/100),g=d.growth||{},j=g.journal||{},eng=d.engagement||{},ses=eng.active_session||{},mile=(g.recent_milestones||[])[0];$('#home-content').innerHTML=`${sectionHead('MARY HOME',pulse.headline||'Mary is here.',pulse.detail||'Your shared context is connected.')}
<article class="card accent hero-row"><img src="./assets/mary-reference.jpeg" alt="Mary"><div><span class="eyebrow">LIVE STATE</span><strong>${escapeHtml(title(c.status||live.status||'idle'))}</strong><small>${escapeHtml(c.current_task||live.current_task||'No active task')}</small></div></article>
<div class="stat-grid"><div class="stat"><span>MOOD</span><strong>${escapeHtml(title(e.primary||c.mood||'neutral'))}</strong><div class="meter"><i style="width:${pct(e.intensity||.12)}"></i></div></div><div class="stat"><span>CONNECTION</span><strong>${escapeHtml(r.label||'Beginning')}</strong><div class="meter"><i style="width:${pct(score)}"></i></div></div><div class="stat"><span>EXPERIENCES</span><strong>${j.records??0}</strong><small>${j.meaningful_records??0} meaningful</small></div><div class="stat"><span>CONVERSATION</span><strong>${escapeHtml(title(ses.mode||eng.mode||'adaptive'))}</strong><small>${ses.turns_remaining?`${ses.turns_remaining} turns in thread`:'adaptive depth'}</small></div></div>
${panel('INNER LIFE',`${dataRow('Semantic memories',g.durable_state?.semantic_memories??0)}${dataRow('Developed preferences',g.durable_state?.developed_preferences??0)}${dataRow('Relationship milestones',g.durable_state?.relationship_milestones??0)}${mile?`<div class="growth-callout"><span>LATEST MILESTONE</span><strong>${escapeHtml(mile.title||'Development milestone')}</strong><small>${escapeHtml(mile.description||'')}</small></div>`:'<p class="hint">Meaningful grounded experience can now feed safe development without treating model dialogue as truth.</p>'}`,'GROWTH')}
${panel('COMPANION PULSE',`<p>${escapeHtml(pulse.detail||'Talk, create, study, focus, or just hang out.')}</p>`,pulse.mode?.toUpperCase()||'LIVE')}
${panel('CURRENT THREADS',list(pulse.top_tasks||[],x=>`<div class="list-item"><div><strong>${escapeHtml(x.title)}</strong><span>${escapeHtml(title(x.kind))}</span></div><span class="tag">${escapeHtml(title(x.status))}</span></div>`,'No active command items.'))}
${panel('PROVIDER ROUTE',`<p>${escapeHtml((d.providers?.effective_conversation_route||[]).join(' → ')||'No effective route reported.')}</p><div class="badges">${(d.providers?.providers||[]).map(p=>`<span class="badge ${p.available?'ready':''}">${escapeHtml(p.name)} · ${p.available?'READY':'OFF'}</span>`).join('')}</div>`,escapeHtml(d.providers?.host||'HOST'))}`;}
function renderCommand(){const command=state.ecosystem.command||{},items=command.items||[];$('#command-content').innerHTML=`${sectionHead('TODAY / PROJECTS','Command Center','Tasks, projects, goals, ideas and waiting threads beside Mary.')}
<article class="card accent"><form id="command-add" class="command-add"><input class="text-input" id="command-title" placeholder="Add something…"><button class="primary" type="submit">Add</button></form><div class="stat-grid"><div class="stat"><span>ACTIVE</span><strong>${command.active??0}</strong></div><div class="stat"><span>WAITING</span><strong>${command.waiting??0}</strong></div></div></article>
${panel('COMMAND ITEMS',list(items,x=>`<div class="list-item command-row"><div><strong>${escapeHtml(x.title||'Untitled')}</strong><span>${escapeHtml(title(x.kind||'task'))} · priority ${escapeHtml(x.priority??0)}</span></div><select data-command-status="${escapeHtml(x.id)}"><option value="active" ${x.status==='active'?'selected':''}>Active</option><option value="waiting" ${x.status==='waiting'?'selected':''}>Waiting</option><option value="done" ${x.status==='done'?'selected':''}>Done</option></select></div>`,'No command items yet.'))}`;bindCommand();}
function bindCommand(){const form=$('#command-add');form?.addEventListener('submit',async e=>{e.preventDefault();const input=$('#command-title'),v=input.value.trim();if(!v)return;try{await bridge('addCommandItem',[v,'task']);input.value='';await refresh({quiet:true});toast('Added to Command Center.');}catch(err){toast(err.message);}});$$('[data-command-status]').forEach(el=>el.addEventListener('change',async()=>{try{await bridge('updateCommandStatus',[el.dataset.commandStatus,el.value]);await refresh({quiet:true});}catch(err){toast(err.message);}}));}
function renderFocus(){clearInterval(state.focusTicker);const f=state.ecosystem.focus||{};$('#focus-content').innerHTML=`${sectionHead('QUIET CO-WORKING','Focus With Mary','A quiet timer using the same persistent Focus state as Desktop.')}
<article class="card accent focus-hero"><div class="focus-ring"><strong id="focus-time">00:00</strong><span id="focus-status">${f.active?'ACTIVE':'IDLE'}</span></div><p id="focus-task">${escapeHtml(f.task||(f.active?'Focus session in progress.':'No active focus task.'))}</p></article>
<article class="panel"><header><span>START A SESSION</span></header><div class="button-row"><button class="action" data-focus="25">25 min</button><button class="action" data-focus="45">45 min</button><button class="action" data-focus="60">60 min</button><button id="focus-stop" class="ghost">Stop</button></div></article>`;const update=()=>{let rem=Number(f.remaining_seconds||0);if(f.active&&f.ends_at)rem=Math.max(0,Math.floor(Number(f.ends_at)-Date.now()/1000));const mm=Math.floor(rem/60),ss=rem%60;const node=$('#focus-time');if(node)node.textContent=`${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;$('.focus-ring')?.style.setProperty('--focus-angle',f.active?'295deg':'15deg');};update();if(f.active)state.focusTicker=setInterval(update,1000);$$('[data-focus]').forEach(b=>b.addEventListener('click',async()=>{try{await bridge('startFocus',[Number(b.dataset.focus),'']);await refresh({quiet:true});toast(`Focus started · ${b.dataset.focus} min`);}catch(e){toast(e.message);}}));$('#focus-stop')?.addEventListener('click',async()=>{try{await bridge('stopFocus',[]);await refresh({quiet:true});toast('Focus stopped.');}catch(e){toast(e.message);}});}
function renderWorkspace(name){const meta=META[name]||['MARY',title(name),''];$('#workspace-eyebrow').textContent=meta[0];$('#workspace-title').textContent=meta[1];$('#workspace-description').textContent=meta[2];const target=$('#workspace-content');const fn={memories:renderMemories,growth:renderGrowth,personality:renderPersonality,mind:renderMind,studio:renderStudio,study:renderStudy,stream:renderStream,gallery:renderGallery,media:renderMedia,voice:renderVoice,runtime:renderRuntime,settings:renderSettings,search:renderSearch,research:renderResearch,arcade:renderArcade}[name];target.innerHTML=fn?fn():`<div class="empty">This workspace is unavailable.</div>`;bindWorkspace(name);}
function renderMemories(){const d=state.dashboard,r=d.relationship||{},score=clamp(Number(r.score||0)/100),g=d.growth||{},j=g.journal||{};return `${panel('OUR CONTINUITY',`${dataRow('Stage',r.label||'Beginning')}${dataRow('Continuity index',`${Math.round(score*100)}%`)}${dataRow('Profile records',r.profile_records??0)}${dataRow('History events',r.history_events??0)}${dataRow('Milestones',r.milestones??0)}${dataRow('Experience journal',j.records??0)}${dataRow('Meaningful experiences',j.meaningful_records??0)}`,'LIVE')}${panel('MEMORY HIGHLIGHTS',list(d.memory_highlights||[],m=>`<div class="list-item"><div><strong>${escapeHtml(m.title)}</strong><span>${escapeHtml(m.label||m.category||'Memory')} · ${escapeHtml(m.key||'')}</span></div><span class="tag">${Math.round(Number(m.confidence||0)*100)}%</span></div>`,'No structured highlights yet.'))}${panel('RECENT ACTIVITY',list(d.recent_activities||[],a=>`<div class="list-item"><div><strong>${escapeHtml(a.title)}</strong><span>${escapeHtml(title(a.kind))}</span></div><span class="tag">${escapeHtml(a.when||'recently')}</span></div>`,'No recent relationship activity.'))}`;}
function renderGrowth(){const g=state.dashboard.growth||{},j=g.journal||{},last=g.last_growth||{},c=g.preference_candidates||[],m=g.recent_milestones||[],policy=g.policy||{},durable=g.durable_state||{},run=g.process_counters||{};return `${panel('EXPERIENCE LOOP',`${dataRow('Experiences retained',j.records??0)}${dataRow('Meaningful experiences',j.meaningful_records??0)}${dataRow('Semantic memories',durable.semantic_memories??0)}${dataRow('Developed preferences',durable.developed_preferences??0)}${dataRow('Developed personality traits',durable.developed_personality_traits??0)}${dataRow('Relationship milestones',durable.relationship_milestones??0)}${last.importance!=null?dataRow('Last significance',`${Math.round(Number(last.importance)*100)}%`):''}`,'DURABLE')}${panel('THIS CORE RUN',`${dataRow('Semantic promotions',run.semantic_promotions??g.semantic_promotions??0)}${dataRow('Preference promotions',run.preference_promotions??g.preference_promotions??0)}${dataRow('Milestones created',run.milestones_created??g.milestones_created??0)}<p class="hint">These activity counters reset when the Mary Core process restarts. Durable state above does not.</p>`,'PROCESS')}${panel('DEVELOPING',list(c,x=>`<div class="list-item"><div><strong>${escapeHtml(x.name)}</strong><span>${escapeHtml(title(x.category))} · ${x.observations||0} grounded observations</span></div><span class="tag ${x.eligible?'ready':''}">${Math.round(Number(x.confidence||0)*100)}%</span></div>`,'No preference-development candidates yet.'))}${panel('MILESTONES',list(m,x=>`<div class="list-item"><div><strong>${escapeHtml(x.title||'Milestone')}</strong><span>${escapeHtml(x.description||'')}</span></div><span class="tag">${escapeHtml(title(x.category||'growth'))}</span></div>`,'No development milestones yet.'))}${panel('DEVELOPMENT BOUNDARY',`<p>Safe semantic consolidation: <b>${policy.automatic_safe_semantic_consolidation?'ON':'OFF'}</b></p><p>Strict grounded preference development: <b>${policy.automatic_strict_preference_development?'ON':'OFF'}</b></p><p>Model dialogue becomes self-evidence: <b>${policy.model_dialogue_counts_as_self_evidence?'YES':'NO'}</b></p><p class="hint">Mary can accumulate grounded development while canonical values and personality remain protected from arbitrary model output.</p>`,'SAFE')}`;}
function renderPersonality(){const p=state.dashboard.personality||{},d=state.dashboard,a=d.agency||{},cur=d.curiosities||[],prefs=p.preferences||[],likes=prefs.filter(x=>Number(x.polarity||0)>=0),dislikes=prefs.filter(x=>Number(x.polarity||0)<0),dev=(d.growth||{}).preference_candidates||[],ds=p.developed_self||{};return `${panel('DEVELOPED SELF',`${dataRow('Developed personality traits',ds.personality_traits??0)}${dataRow('Developed preferences',ds.preferences??0)}<p class="hint">Authored Mary remains the baseline. Only approved or grounded development paths appear as developed state.</p>`,'PROVENANCE')}${panel('TRAITS',(p.traits||[]).map(t=>`<div class="trait-row"><span>${escapeHtml(title(t.name))}</span><div class="meter"><i style="width:${pct(t.value)}"></i></div><b>${Math.round(Number(t.value||0)*100)}${t.authority==='developed'?' · D':''}</b></div>`).join('')||'<div class="empty">No trait state represented.</div>','SELF')}${panel('VALUES',list(p.values||[],v=>`<div class="list-item"><div><strong>${escapeHtml(v.name)}</strong><span>${escapeHtml(v.description||'')}</span></div><span class="tag">${Math.round(Number(v.strength||0)*100)}</span></div>`))}${panel('LIKES / INTERESTS',list(likes,v=>`<div class="list-item"><div><strong>${escapeHtml(v.name)}</strong><span>${escapeHtml(title(v.category))} · ${escapeHtml(title(v.authority||'authored'))}</span></div><span class="tag">${Math.round(Number(v.strength||0)*100)}</span></div>`,'No represented likes yet.'))}${panel('DISLIKES / AVERSIONS',list(dislikes,v=>`<div class="list-item"><div><strong>${escapeHtml(v.name)}</strong><span>${escapeHtml(title(v.category))} · ${escapeHtml(title(v.authority||'authored'))}</span></div><span class="tag">${Math.round(Number(v.strength||0)*100)}</span></div>`,'No represented dislikes yet.'))}${panel('DEVELOPING',list(dev,v=>`<div class="list-item"><div><strong>${escapeHtml(v.name)}</strong><span>${v.observations||0} grounded observations · ${escapeHtml(title(v.category))}</span></div><span class="tag">${v.eligible?'ELIGIBLE':'WATCH'}</span></div>`,'No active development candidates.'))}${panel('AGENCY',`${dataRow('Active goals',a.active_goals??0)}${dataRow('Active intentions',a.active_intentions??0)}${dataRow('Open curiosities',a.open_curiosities??0)}${list(cur,c=>`<div class="list-item"><div><strong>${escapeHtml(c.description)}</strong><span>${escapeHtml(title(c.status))}</span></div><span class="tag">${Math.round(Number(c.importance||0)*100)}%</span></div>`,'No represented curiosities.')}`,'LIVE')}`;}
function renderMind(){const m=state.mind||{};return `${panel('LOCAL MIND',`${dataRow('Enabled',m.enabled===false?'No':'Yes')}${dataRow('Engine',m.engine||m.provider||m.kind||'Mary local mind')}${dataRow('Records',m.records??m.record_count??m.reservoir_records??m.reservoir?.records??'—')}${dataRow('Model',m.model||'—')}<p class="mono">${escapeHtml(m.error||m.status||m.summary||'Local deterministic and model-assisted fast paths remain behind Mary’s canonical cognition.')}</p>`,'LOCAL')}<button id="mind-rebuild" class="action wide">Rebuild cognitive reservoir</button>`;}
function renderStudio(){const s=state.studio.state; if(!s)return `${panel('CREATIVE WORKSPACE','<p>Load the workspace Mary’s host already has configured. The phone never receives arbitrary filesystem access.</p>','SAFE')}<button id="studio-load" class="primary wide">Load Studio</button>`;if(!s.configured)return `${panel('CREATIVE WORKSPACE',`<p>${escapeHtml(s.error||'No creative workspace is configured on Mary’s host. Set MARY_CREATIVE_WORKSPACE there or select it once from Desktop.')}</p>`,'NOT SET')}<button id="studio-load" class="ghost wide">Refresh</button>`;const files=s.files||[];return `${panel('PROJECT',`${dataRow('Name',s.name)}${dataRow('Files',s.file_count??files.length)}${dataRow('Editable',s.editable_count??0)}<p class="mono">${escapeHtml(s.root||'')}</p>`,'CONNECTED')}<div class="card"><div class="section-title">FILES</div><div class="file-list">${files.length?files.map(f=>`<button class="file-button" data-studio-file="${escapeHtml(f.path)}" ${f.editable?'':'disabled'}><strong>${escapeHtml(f.name)}</strong><small>${escapeHtml(f.path)} · ${escapeHtml(f.kind)}${f.editable?'':' · reference only'}</small></button>`).join(''):'<div class="empty">No supported files found.</div>'}</div></div><article id="studio-editor" class="card studio-editor ${state.studio.path?'':'hidden'}"><form id="studio-form" class="form-stack"><label><span id="studio-path">${escapeHtml(state.studio.path)}</span><textarea id="studio-text">${escapeHtml(state.studio.content)}</textarea></label><button class="primary wide" type="submit">Save to creative workspace</button></form></article>`;}
function renderStudy(){const s=state.ecosystem.study||{},due=s.due_cards||[],projects=s.projects_list||s.items||[];return `${panel('STUDY STATUS',`${dataRow('Projects',s.projects??projects.length??0)}${dataRow('Due now',s.due??due.length??0)}${dataRow('Cards',s.cards??'—')}`,'LIVE')}<article class="card"><form id="study-create" class="form-stack"><label><span>NEW STUDY PROJECT</span><input id="study-title" placeholder="Project title"></label><label><span>OBJECTIVE</span><input id="study-objective" placeholder="What are you learning?"></label><button class="primary wide" type="submit">Create project</button></form></article>${panel('DUE CARDS',list(due,c=>`<div class="list-item"><div><strong>${escapeHtml(c.front||c.question||c.prompt||'Study card')}</strong><span>${escapeHtml(c.back||c.answer||'')}</span></div><span class="tag">DUE</span></div>`,'Nothing due right now.'))}`;}
