function renderGallery(){const refs=(state.studio.state?.files||[]).filter(f=>f.kind==='image');return `<div class="gallery-grid"><div class="gallery-card"><img src="./assets/mary-reference.jpeg" alt="Mary"><span>Mary · Companion Portrait</span></div><div class="gallery-card"><img src="./assets/mary-neon-reference-sheet.png" alt="Mary neon visual reference sheet"><span>Mary · Neon Reference Study</span></div><div class="gallery-card"><img src="./assets/mary-gala-reference.png" alt="Mary gala visual reference"><span>Mary · Gala Visual Study</span></div><div class="gallery-card"><img src="./assets/mary-icon.png" alt="Mary icon"><span>Mary · App Icon</span></div></div>${panel('VISUAL PROVENANCE','<div class="list-item"><div><strong>Gala study</strong><span>Optional generated visual reference · not autobiographical memory or automatic canon.</span></div><span class="tag">REFERENCE</span></div>')}${panel('PROJECT REFERENCES',list(refs,x=>`<div class="list-item"><div><strong>${escapeHtml(x.name)}</strong><span>${escapeHtml(x.path)}</span></div><span class="tag">IMAGE</span></div>`,'Load Studio to list project image references.'))}`;}
